def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    cols = [c for c in np.unique(g) if c != 0]
    rects = []
    for c in cols:
        m = g == c
        core = np.zeros_like(m)
        for y in range(H - 1):
            for x in range(W - 1):
                if m[y:y+2, x:x+2].all():
                    core[y:y+2, x:x+2] = True
        # join core fragments through straight runs of the same colour
        while True:
            expanded = core.copy()
            for axis in [0, 1]:
                cm = core if axis == 0 else core.T
                mm = m if axis == 0 else m.T
                em = expanded if axis == 0 else expanded.T
                for row in range(cm.shape[0]):
                    seeds = np.flatnonzero(cm[row])
                    for left, right in zip(seeds[:-1], seeds[1:]):
                        if mm[row, left:right+1].all():
                            em[row, left:right+1] = True
            if np.array_equal(expanded, core):
                break
            core = expanded
        for comp in components(core):
            if len(comp) >= 9:
                rects.append((c, bbox(comp)))

    # priority: share of overlap cells holding own colour (dominant drawn last)
    def prio(i):
        c, (y0, x0, y1, x1) = rects[i]
        tot = own = 0
        for j, (c2, (a0, b0, a1, b1)) in enumerate(rects):
            if j == i:
                continue
            ya, yb, xa, xb = max(y0, a0), min(y1, a1), max(x0, b0), min(x1, b1)
            if ya > yb or xa > xb:
                continue
            sub = g[ya:yb+1, xa:xb+1]
            tot += sub.size
            own += (sub == c).sum()
        return own / tot if tot else 0

    order = sorted(range(len(rects)), key=prio)
    out = np.zeros_like(g)
    owner = -np.ones((H, W), int)
    for i in order:
        c, (y0, x0, y1, x1) = rects[i]
        out[y0:y1+1, x0:x1+1] = c
        owner[y0:y1+1, x0:x1+1] = i
        emit(out, f"Paint clean rectangle of colour {c} at rows {y0}-{y1}, cols {x0}-{x1} (strays dropped, dominant overlap on top)")

    holes = [(y, x) for y in range(H) for x in range(W) if owner[y, x] >= 0 and g[y, x] == 0]
    for (y, x) in holes:
        c = rects[owner[y, x]][0]
        other = [k for k in cols if k != c]
        oc = other[0] if other else c
        out[max(0, y-1):y+2, max(0, x-1):x+2] = oc
    emit(out, "Stamp a 3x3 box of the other region colour around every hole")
    for (y, x) in holes:
        out[y, x] = 8
    emit(out, "Mark each hole centre with 8")
    return out
